    /**
     * Tests getting all PaymentCards.
     *
     * @return    Collection
     */
    public List<PaymentCard> testGetAll() throws Throwable {
    LOGGER.info( "PaymentCardTest:testGetAll() - Retrieving Collection of PaymentCards:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all PaymentCard : " );
    List<PaymentCard> collection  = null;

    try {
        // call the static get method on the PaymentCardService
        collection = service.getAllPaymentCard();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            PaymentCard currEntity  = null;
            Iterator<PaymentCard> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getPaymentCardId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

